  ('Fallas comunes en PlayStation / Consolas','reparacion','https://images.unsplash.com/photo-1606813907291-d86efa9b94db?auto=format&fit=crop&w=1200&q=85','Diagnóstico para consolas con problemas de encendido, video, temperatura, almacenamiento, puertos o conectividad.','["No responde al botón de encendido","Enciende y se apaga","El televisor no recibe señal","Presenta alertas o fallas durante el juego"]'::jsonb,'["No enciende","No da imagen","Se apaga","Se sobrecalienta","Ventilador con ruido","Problemas HDMI","Problemas de almacenamiento","Problemas de conectividad","Problemas con controles","Problemas con puertos"]'::jsonb,'["Alimentación","Sistema térmico","Puerto y circuito HDMI","Almacenamiento","Conectividad","Puertos, controles u otros componentes"]'::jsonb,false,true),
  ('Fallas comunes en Redes / Routers','reparacion','https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1200&q=85','Revisión de problemas de conectividad, cobertura, direccionamiento, cableado y comunicación entre equipos de red.','["La conexión se pierde de forma intermitente","Algunos equipos no navegan","La señal no cubre las áreas esperadas","Routers o access points se reinician"]'::jsonb,'["Internet lento","Pérdida de conexión","Wi-Fi con poca cobertura","Equipos que no obtienen IP","Problemas DHCP","Interferencias","Cableado defectuoso","Conectores dañados","Router/AP con reinicios","Configuración incorrecta","Problemas entre router principal y Access Points"]'::jsonb,'["Router o access point","Fuente de alimentación","Configuración y DHCP","Canales e interferencias","Cableado y conectores","Topología y enlace entre equipos"]'::jsonb,false,true),
  ('Otros problemas tecnológicos','reparacion','https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1200&q=85','Si tu dispositivo presenta otra falla, podemos inspeccionarlo y definir qué pruebas técnicas corresponden.','["El equipo no funciona como antes","Presenta errores intermitentes","Tiene conectores o controles con problemas","No sabes cómo identificar el origen de la falla"]'::jsonb,'["Problemas de encendido","Fallas de funcionamiento","Errores de conectividad","Daños en puertos o conectores","Comportamiento intermitente"]'::jsonb,'["Alimentación","Conectividad","Controles y puertos","Componentes internos accesibles","Otras áreas definidas después de la inspección"]'::jsonb,false,true)
)
insert into public.services(title,category,image_url,description,includes,problems,recommendations,featured,active)
select seed.* from seed
where not exists (
  select 1 from public.services current
  where current.category=seed.category and current.title=seed.title
);

commit;
